<?php require __DIR__.'/../app/bootstrap.php';require_login();$u=current_user($pdo);$s=$pdo->prepare('SELECT * FROM data_transactions WHERE user_id=? ORDER BY id DESC LIMIT 100');$s->execute([$u['id']]);$rows=$s->fetchAll();require __DIR__.'/../app/layout.php';header_html('Transactions');?><div class="card"><h2>Data Transactions</h2><div class="table-wrap"><table><tr><th>Date</th><th>Network</th><th>Phone</th><th>Plan</th><th>Amount</th><th>Status</th><th>Reference</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['network'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['plan'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['status'])?></td><td><?=e($r['provider_reference']??'-')?></td></tr><?php endforeach;?></table></div></div><?php footer_html();
